import{_ as e,c as a,o as r,ae as o}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"How to Create Ninja Charts with Fluent Forms Entries","description":"How to Create Ninja Charts with Fluent Forms Entries","frontmatter":{"title":"How to Create Ninja Charts with Fluent Forms Entries","description":"How to Create Ninja Charts with Fluent Forms Entries"},"headers":[],"relativePath":"guide/ninja-charts/create-ninja-charts-with-fluent-forms-entries.md","filePath":"guide/ninja-charts/create-ninja-charts-with-fluent-forms-entries.md"}'),s={name:"guide/ninja-charts/create-ninja-charts-with-fluent-forms-entries.md"};function n(i,t,c,h,l,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="how-to-create-ninja-charts-with-fluent-forms-entries" tabindex="-1">How to Create Ninja Charts with Fluent Forms Entries <a class="header-anchor" href="#how-to-create-ninja-charts-with-fluent-forms-entries" aria-label="Permalink to &quot;How to Create Ninja Charts with Fluent Forms Entries&quot;">​</a></h1><p>Suppose you want to create different online charts on your website. Ninja Charts is a powerful chart generator that helps you create, customize, and embed numerous types of charts in WordPress. And if you have a WordPress form by Fluent Forms, you can make a chart with the form entries. It&#39;s super easy too!</p><h2 id="create-charts-with-fluent-forms-entries" tabindex="-1">Create Charts with Fluent Forms Entries <a class="header-anchor" href="#create-charts-with-fluent-forms-entries" aria-label="Permalink to &quot;Create Charts with Fluent Forms Entries&quot;">​</a></h2><p>First of all, you need to pick the chart renderer (Charts Js or Google Charts). Then pick a chart type from the 10+ options. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Create-a-chart-01-1024x580.webp" alt="Create a chart"></p><h3 id="select-fluent-forms-as-chart-data-source" tabindex="-1">Select Fluent Forms as Chart Data Source <a class="header-anchor" href="#select-fluent-forms-as-chart-data-source" aria-label="Permalink to &quot;Select Fluent Forms as Chart Data Source&quot;">​</a></h3><p>You can see 3 options Ninja Charts offers to create charts using different data sources.</p><ul><li>Manual Input: Users can input their own data manually</li><li>Ninja Tables: Create chart using a table</li><li>Fluent Forms: Create chart using form entries We&#39;ll select Fluent Forms as the chart data source. <img src="https://ninjatables.com/wp-content/uploads/2025/08/Select-Fluent-Forms-as-chart-data-source-1024x416.webp" alt="Select Fluent Forms as chart data source"> Once you select the source, another option will appear asking for &quot;Data.&quot; This is where you select the form you want to appear on your new chart. <img src="https://ninjatables.com/wp-content/uploads/2025/08/Select-a-form-to-populate-chart-1024x386.webp" alt="Select a form to populate Ninja Charts"> Hit &quot;Next&quot; after selecting a form and move to customizing <a href="https://ninjatables.com/docs/how-to-use-data-range-picker-in-ninja-charts/" target="_blank" rel="noreferrer">Data Range</a>, <a href="https://ninjatables.com/docs/how-to-customize-charts-in-ninja-charts/" target="_blank" rel="noreferrer">Formatting &amp; Preview</a>, and save the Fluent Forms data chart. <strong>Tip</strong>: Be mindful of the data type of the form you&#39;re selecting and the chart type. Forms with text input are not suitable for pie chart or radar. For Ninja Charts to correctly populate form entries, you need to pick the correct form and the correct chart type.</li></ul>',7)])])}const f=e(s,[["render",n]]);export{p as __pageData,f as default};
